122			hi++
123		}
124		for n := 0; ; n++ {
125			c, ok := src.at(hi)
126			if !ok || !isSeparator(c) {
127				break
128			}
129			if n >= maxSeparatorRun {
130				return 0, 0, errSeparatorRun
131			}
132			hi++
133		}
134		lo = max(0, lo-salientWindow)
135		for k := 0; k < salientWindow; k++ {
136			if _, ok := src.at(hi); !ok {
137				break
138			}
139			hi++
140		}
141		return lo, hi, nil
142	}
143	
144	// salientMatch reports whether b contains failure evidence.
145	func salientMatch(b []byte) (bool, error) {
146		hits, err := salientHits(sliceSource(b), 0, b, 1)
147		return len(hits) > 0, err
148	}
149	
150	// scanSalient records every failure-evidence position in the document once.
151	func (s *src) scanSalient(ctx context.Context) error {
152		const chunk, overlap = 1 << 20, 2 * salientWindow
153		s.salientPos = s.salientPos[:0]
154		buf := make([]byte, chunk) // one reusable chunk buffer
155		for off := int64(0); off < s.n; off += chunk - overlap {
156			if err := ctx.Err(); err != nil {
157				return err
158			}
159			end := min(s.n, off+chunk)
160			m, _ := s.r.ReadAt(buf[:end-off], off)
161			hits, err := salientHits(s, off, buf[:m], maxSalientPositions)
162			if err != nil {
163				return err
164			}
165			for _, h := range hits {
166				s.salientPos = append(s.salientPos, off+int64(h))
167			}
168			if len(s.salientPos) >= maxSalientPositions {
169				// the detection budget is exhausted: later mandatory failures could be
170				// missed, so the document is refused explicitly rather than reduced
171				return fmt.Errorf("%w: more than %d failure-evidence positions", ErrUnsupported, maxSalientPositions)
172			}
173			if end == s.n {
174				break
175			}
176		}
177		sort.Slice(s.salientPos, func(a, b int) bool { return s.salientPos[a] < s.salientPos[b] })
178		s.salientIndexed = true
179		return nil
180	}
181	
182	// salientIn reports whether [a,b) contains failure evidence.
183	func (s *src) salientIn(a, b int64) bool {
184		if !s.salientIndexed || s.salientSaturated {
185			ok, _ := salientMatch(s.read(a, min(b, a+64<<10)))
186			return ok
187		}
188		i := sort.Search(len(s.salientPos), func(k int) bool { return s.salientPos[k] >= a })
189		return i < len(s.salientPos) && s.salientPos[i] < b
190	}
191	
192	// salientRange returns up to limit evidence positions in [a,b), at least `gap` apart.
193	func (s *src) salientRange(a, b int64, limit int, gap int64) []int64 {
194		var out []int64
195		if !s.salientIndexed || s.salientSaturated {
196			buf := s.read(a, min(b, a+(1<<20)))
197			hits, _ := salientHits(sliceSource(buf), 0, buf, limit)
198			for _, h := range hits {
199				out = append(out, a+int64(h))
200			}
201			sort.Slice(out, func(x, y int) bool { return out[x] < out[y] })
202			return out
203		}
204		i := sort.Search(len(s.salientPos), func(k int) bool { return s.salientPos[k] >= a })
205		for ; i < len(s.salientPos) && s.salientPos[i] < b && len(out) < limit; i++ {
206			if len(out) == 0 || s.salientPos[i]-out[len(out)-1] > gap {
207				out = append(out, s.salientPos[i])
208			}
209		}
210		return out
211	}
